package com.inventory.skillgapanalysisbackend.controller;
import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/learning") public class LearningController { @GetMapping("/path") public Map<String,Object> path(@RequestParam(defaultValue="Java Backend Developer") String role){Map<String,List<String>> paths=Map.of("Java Backend Developer",List.of("Core Java and OOP","Collections and exceptions","SQL and database design","REST APIs with Spring Boot","Spring Data JPA","Testing and deployment"),"Frontend Developer",List.of("HTML semantics","CSS and responsive design","JavaScript fundamentals","React components and hooks","API integration","Testing and deployment"),"Data Analyst",List.of("Excel","SQL","Statistics","Python and pandas","Data visualization","Portfolio case study"),"AI/ML Engineer",List.of("Python","Linear algebra and statistics","pandas and NumPy","Machine learning fundamentals","Model evaluation","End-to-end portfolio project"));List<String> steps=paths.getOrDefault(role,paths.get("Java Backend Developer"));List<Map<String,Object>> out=new ArrayList<>();for(int i=0;i<steps.size();i++)out.add(Map.of("step",i+1,"topic",steps.get(i),"completed",false));return Map.of("targetRole",role,"learningPath",out);}}
